//! What the module's routes answer with. TypeScript bindings are generated by `cargo test`.
//! Every date is a day, `YYYY-MM-DD`.

use hub_core::{Id, SprintState, StatusCategory, WorkCounts};
use serde::Serialize;
use ts_rs::TS;

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct TimelineStatus {
    pub id: Id,
    pub name: String,
    pub category: StatusCategory,
}

/// Which ends of a span nobody set: they were worked out from the issue's children.
#[derive(Debug, Clone, Copy, Default, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct TimelineDerived {
    pub start: bool,
    pub due: bool,
}

/// When an issue's work runs. An end that is set is the issue's own (the start kept by this
/// module, the due date the tracker's); one that is missing is estimated from the children
/// and marked in `derived`. Null where there is nothing to go by.
#[derive(Debug, Clone, Default, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct TimelineSpan {
    pub start: Option<String>,
    pub due: Option<String>,
    pub derived: TimelineDerived,
}

/// An issue under an epic. Its dates are its own, never estimated.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct TimelineChild {
    pub id: Id,
    pub key: String,
    pub summary: String,
    pub status: TimelineStatus,
    pub assignee_id: Option<Id>,
    pub start: Option<String>,
    pub due: Option<String>,
}

/// One row of the timeline: an epic, what is under it and when it runs.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct TimelineEpic {
    pub id: Id,
    pub key: String,
    pub summary: String,
    pub status: TimelineStatus,
    pub assignee_id: Option<Id>,
    #[serde(flatten)]
    pub span: TimelineSpan,
    /// The children by the category of their status.
    pub counts: WorkCounts,
    /// Story points of the children that are done.
    pub points_done: f64,
    /// Story points of all children; 0 when nothing is estimated.
    pub points_total: f64,
    /// In rank order.
    pub children: Vec<TimelineChild>,
}

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct TimelineSprint {
    pub id: Id,
    pub name: String,
    pub state: SprintState,
    pub start: Option<String>,
    /// The planned end; for a sprint completed without one, the day it was completed.
    pub end: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct TimelineVersion {
    pub id: Id,
    pub name: String,
    pub released: bool,
    /// The planned date; for a version released without one, the day it was released.
    pub release_date: Option<String>,
}

/// Everything the timeline page of a project shows.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct TimelineProject {
    pub project_key: String,
    /// The epics in rank order.
    pub epics: Vec<TimelineEpic>,
    pub sprints: Vec<TimelineSprint>,
    /// Versions that are not archived.
    pub versions: Vec<TimelineVersion>,
    /// Whether the caller may change dates.
    pub can_edit: bool,
}
